def parse_date_safe(s):
    if not s or not isinstance(s, str):
        return None
    try:
        return dtparser.parse(s, fuzzy=True)
    except Exception:
        return None

# Parse grant_date and filter to H2 2019
df['grant_dt'] = df['grant_date'].map(parse_date_safe)
df['filing_dt'] = df['filing_date'].map(parse_date_safe)

print('Null grant:', df['grant_dt'].isna().sum())
print('Null filing:', df['filing_dt'].isna().sum())

# Identify Germany cohort using inventor_harmonized
def is_german(inv_text):
    if not inv_text or not isinstance(inv_text, str):
        return False
    try:
        inv = json.loads(inv_text)
        if isinstance(inv, list):
            for it in inv:
                if isinstance(it, dict) and it.get('country_code') == 'DE':
                    return True
        return False
    except Exception:
        # fallback string check
        return '"country_code": "DE"' in inv_text

cohort['is_de'] = cohort['inventor_harmonized'].map(is_german)
# Also check Patents_info patterns
def patents_info_de(t):
    if not t or not isinstance(t, str):
        return False
    return ('In DE,' in t) or ('DE patent' in t) or ('Germany' in t)

cohort['pinfo_de'] = cohort['Patents_info'].map(patents_info_de)
print('inventor DE:', cohort['is_de'].sum())
print('patents_info DE:', cohort['pinfo_de'].sum())
print('either:', (cohort['is_de'] | cohort['pinfo_de']).sum())

# Extract CPC codes
def parse_cpc(s):
    if not s or not isinstance(s, str):
        return []
    try:
        arr = json.loads(s)
        codes = []
        for d in arr:
            if isinstance(d, dict) and 'code' in d:
                codes.append(d['code'])
        return codes
    except Exception:
        return []

de_cohort['cpc_codes'] = de_cohort['cpc'].map(parse_cpc)
de_cohort['cpc_codes'] = de_cohort['cpc_codes'].map(lambda lst: list(set(lst)))  # dedup per patent
print('Distinct cpc codes across cohort:', len(set(c for lst in de_cohort['cpc_codes'] for c in lst)))
all_codes_cohort = set(c for lst in de_cohort['cpc_codes'] for c in lst)
print(list(all_codes_cohort)[:20])

# Get all symbols + level + parents
all_rows = conn_pg.execute('SELECT symbol, level, parents, "titleFull" FROM cpc_definition').fetchall()
print('Total:', len(all_rows))
level_map = {}  # symbol -> level
parents_map = {}  # symbol -> list of parent symbols
title_map = {}  # symbol -> titleFull
for s, lvl, par, tf in all_rows:
    level_map[s] = lvl
    title_map[s] = tf
    if par:
        try:
            pj = json.loads(par)
            if isinstance(pj, list):
                # could be list of dicts or list of strings
                ps = []
                for item in pj:
                    if isinstance(item, dict) and 'symbol' in item:
                        ps.append(item['symbol'])
                    elif isinstance(item, str):
                        ps.append(item)
                parents_map[s] = ps
            else:
                parents_map[s] = []
        except Exception:
            parents_map[s] = []
    else:
        parents_map[s] = []

# Check sample parents
for s in list(parents_map.keys())[:5]:
    print(s, '->', parents_map[s])

# Build cache: cpc_code -> level-4 ancestor symbol
def find_level4(code):
    if code in level_map:
        if level_map[code] == 4:
            return code
        # check parents
        for p in parents_map.get(code, []):
            if level_map.get(p) == 4:
                return p
        # walk up
        for p in parents_map.get(code, []):
            anc = find_level4(p)
            if anc:
                return anc
        return None
    # If not in map, try to deduce: level-4 codes look like 'F16H', 'A61K', etc.
    # Try prefix matching to find level-4 symbol
    # Level-4 CPC codes are typically 4-letter group (e.g., 'F16H')
    # Check if code starts with something that matches a level-4
    for length in range(len(code), 0, -1):
        prefix = code[:length]
        if level_map.get(prefix) == 4:
            return prefix
    return None

# Compute for each cohort code
cpc_to_l4 = {}
for c in all_codes_cohort:
    cpc_to_l4[c] = find_level4(c)

unmapped = [c for c, v in cpc_to_l4.items() if v is None]
print('Unmapped cohort codes:', len(unmapped), '/', len(all_codes_cohort))
print(unmapped[:10])
print('Distinct level-4 groups:', len(set(v for v in cpc_to_l4.values() if v)))

# Check levels for some sample codes
for s in ['A', 'A01', 'A01B', 'A01B1/00', 'F16H', 'F16H47', 'F16H47/04', 'H01L', 'H01L21', 'H01L21/324']:
    print(s, level_map.get(s))
